# This script will rank candidate failure-avoiding (generated by run/candidates.py) patterns through the following ranking distribution:
#  1. failure-free runs have total priority;
#  2. failing runs by maximum progress (`log/progress`), then steps survived;
#  3. within a group, by risk: lowest predicted failure probability and
#     largest margin to a failure rule first;
#  4. task reward only breaks remaining ties

import argparse
import json
import pathlib
import numpy as np

def get(row, key, default):
    value = row.get(key)
    return default if value is None else value

def rank_key(row):
    failed = row['failed']
    return (
        failed,
        not row['goal'],
        -get(row, 'max_progress', 0.0),
        -row['length'] if failed else 0,         
        get(row, 'max_pfail', 0.0),               
        -get(row, 'min_margin', 0.0),             
        -get(row, 'score', 0.0),
    )    

def load_actions(folder, index):
    data = np.load(folder / f'cand_{index:06d}.npz')
    keys = sorted(k for k in data.files if k.startswith('act_')) 
    return np.concatenate(
        [data[k].reshape(len(data[k]), -1).astype(np.float32) for k in keys], 1)

def distinct(a, b, threshold):
    if len(a) != len(b):
        return True
    return np.abs(a - b).mean() > threshold    

def deduplicate(folder, ranked, threshold):
    kept, kept_actions = [], []
    for row in ranked:
        acts = load_actions(folder, row['index'])
        for group, other in zip(kept, kept_actions):
            if not distinct(acts, other, threshold):
                group['support'] += 1
                group['group_failures'] += int(row['failed'])
                break
        else:
            kept.append({**row, 'support': 1, 'group_failures': int(row['failed'])})
            kept_actions.append(acts)
    for group in kept:
        group['group_fail_rate'] = group['group_failures'] / group['support']
    return kept
            
def main():
  parser = argparse.ArgumentParser()
  parser.add_argument('candidates', type=pathlib.Path)
  parser.add_argument('--top', type=int, default=10)
  parser.add_argument('--threshold', type=float, default=0.05)
  args = parser.parse_args()

  lines = (args.candidates / 'summary.jsonl').read_text().splitlines()
  rows = [json.loads(line) for line in lines if line.strip()]
  ranked = sorted(rows, key=rank_key)
  ranked = deduplicate(args.candidates, ranked, args.threshold)

  with open(args.candidates / 'ranked.jsonl', 'w') as f:
    for rank, row in enumerate(ranked):
      f.write(json.dumps({'rank': rank, **row}) + '\n')

  for rank, row in enumerate(ranked[:args.top]):
    print(rank, row)


if __name__ == '__main__':
  main()   